package com.gpcbellary.cms.controller;
import com.gpcbellary.cms.repository.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/dashboard") @CrossOrigin public class DashboardController{
 private final StudentRepository s;private final TeacherRepository t;private final DepartmentRepository d;private final NoticeRepository n;private final CollegeEventRepository e;private final FeeBillRepository f;private final AdmissionRepository a;private final ResultRepository r;private final CompanyRepository c;
 public DashboardController(StudentRepository s,TeacherRepository t,DepartmentRepository d,NoticeRepository n,CollegeEventRepository e,FeeBillRepository f,AdmissionRepository a,ResultRepository r,CompanyRepository c){this.s=s;this.t=t;this.d=d;this.n=n;this.e=e;this.f=f;this.a=a;this.r=r;this.c=c;}
 @GetMapping public Map<String,Object> dashboard(){Map<String,Object> m=new LinkedHashMap<>();m.put("students",s.count());m.put("teachers",t.count());m.put("departments",d.count());m.put("notices",n.count());m.put("events",e.count());m.put("admissions",a.count());m.put("results",r.count());m.put("companies",c.count());BigDecimal total=f.findAll().stream().map(x->x.getAmount()==null?BigDecimal.ZERO:x.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal paid=f.findAll().stream().map(x->x.getPaidAmount()==null?BigDecimal.ZERO:x.getPaidAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);m.put("totalFees",total);m.put("paidFees",paid);m.put("pendingFees",total.subtract(paid));return m;}
}
